import { X, Box, Truck, CheckCircle2, AlertCircle } from 'lucide-react';

const TRUCK_CAPACITIES = [
  { type: 'jumbo4m', name: 'Jumbo 4M', capacityCbm: 21.0, color: 'from-indigo-600 to-blue-700' },
  { type: 'jumbo', name: 'Jumbo Standard', capacityCbm: 9.5, color: 'from-pink-600 to-purple-700' },
  { type: 'dabbaba', name: 'Dabbaba', capacityCbm: 5.0, color: 'from-amber-500 to-orange-600' },
];

const ITEM_COLORS = [
  'bg-blue-500 border-blue-600 text-white',
  'bg-emerald-500 border-emerald-600 text-white',
  'bg-purple-500 border-purple-600 text-white',
  'bg-amber-500 border-amber-600 text-white',
  'bg-rose-500 border-rose-600 text-white',
  'bg-cyan-500 border-cyan-600 text-white',
  'bg-indigo-500 border-indigo-600 text-white',
  'bg-teal-500 border-teal-600 text-white',
];

const TruckVisualizerModal = ({ order, onClose }) => {
  const [selectedTruckIndex, setSelectedTruckIndex] = useState(0);

  if (!order) return null;

  const totalCbm = order.totalCbm || 0;
  const items = order.items || [];

  const activeTrucks = [];
  if (order.recommendedTrucks?.jumbo4m > 0) activeTrucks.push(TRUCK_CAPACITIES[0]);
  if (order.recommendedTrucks?.jumbo > 0) activeTrucks.push(TRUCK_CAPACITIES[1]);
  if (order.recommendedTrucks?.dabbaba > 0) activeTrucks.push(TRUCK_CAPACITIES[2]);

  const truckOptions = activeTrucks.length > 0 ? activeTrucks : TRUCK_CAPACITIES;
  const currentTruck = truckOptions[selectedTruckIndex] || truckOptions[0];

  const fillPercentage = Math.min(100, Math.round((totalCbm / currentTruck.capacityCbm) * 100));
  const remainingCbm = Math.max(0, currentTruck.capacityCbm - totalCbm);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 backdrop-blur-xs p-4 overflow-y-auto">
      <div className="bg-white rounded-2xl shadow-2xl border border-slate-200 w-full max-w-4xl overflow-hidden animate-in fade-in zoom-in duration-200">

        {/* Modal Header */}
        <div className="bg-slate-900 text-white p-5 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-indigo-500/20 border border-indigo-400/30 rounded-xl">
              <Truck className="w-6 h-6 text-indigo-400" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h2 className="text-xl font-bold tracking-tight">{order.branchName}</h2>
                <span className="text-xs bg-slate-800 text-slate-300 px-2.5 py-0.5 rounded-full border border-slate-700">
                  {order.zone || 'General Zone'}
                </span>
              </div>
              <p className="text-xs text-slate-400 mt-0.5">3D Cargo Load Simulation & Capacity Visualizer</p>
            </div>
          </div>

          <button 
            onClick={onClose}
            className="p-2 text-slate-400 hover:text-white hover:bg-slate-800 rounded-xl transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Modal Content */}
        <div className="p-6 space-y-6">

          {/* Truck Selector & Fill Progress */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 bg-slate-50 p-4 rounded-xl border border-slate-200">
            <div>
              <label className="text-xs font-bold text-slate-500 uppercase tracking-wider block mb-1.5">Select Truck Model</label>
              <div className="flex flex-wrap gap-2">
                {truckOptions.map((t, idx) => (
                  <button
                    key={t.type}
                    onClick={() => setSelectedTruckIndex(idx)}
                    className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all border ${
                      selectedTruckIndex === idx 
                        ? 'bg-slate-900 text-white border-slate-900 shadow-sm' 
                        : 'bg-white text-slate-700 border-slate-200 hover:bg-slate-100'
                    }`}
                  >
                    {t.name} ({t.capacityCbm} m³)
                  </button>
                ))}
              </div>
            </div>

            <div>
              <span className="text-xs font-bold text-slate-500 uppercase tracking-wider block mb-1.5">Cargo Fill Rate</span>
              <div className="flex items-center gap-2">
                <div className="flex-1 bg-slate-200 rounded-full h-4 overflow-hidden border border-slate-300 relative">
                  <div 
                    className={`h-full transition-all duration-500 bg-gradient-to-r ${
                      fillPercentage > 100 ? 'from-red-500 to-rose-600' : fillPercentage > 85 ? 'from-emerald-500 to-teal-600' : 'from-indigo-500 to-blue-600'
                    }`}
                    style={{ width: `${Math.min(100, fillPercentage)}%` }}
                  />
                </div>
                <span className="text-sm font-extrabold text-slate-800">{fillPercentage}%</span>
              </div>
            </div>

            <div className="flex items-center justify-around text-center border-l border-slate-200 pl-4">
              <div>
                <span className="text-[11px] text-slate-400 font-semibold block uppercase">Total Cargo</span>
                <span className="text-base font-extrabold text-indigo-600">{totalCbm.toFixed(2)} CBM</span>
              </div>
              <div>
                <span className="text-[11px] text-slate-400 font-semibold block uppercase">Remaining</span>
                <span className={`text-base font-extrabold ${remainingCbm === 0 ? 'text-amber-600' : 'text-emerald-600'}`}>
                  {remainingCbm.toFixed(2)} CBM
                </span>
              </div>
            </div>
          </div>

          {/* Visual Truck Cargo Bed */}
          <div className="relative">
            <div className="flex items-center justify-between mb-2">
              <span className="text-xs font-bold text-slate-700 uppercase tracking-wider flex items-center gap-1.5">
                <Box className="w-4 h-4 text-indigo-600" />
                Truck Cargo Space Layout ({currentTruck.name})
              </span>
              <span className="text-xs text-slate-400">Cabin Driver Side ← Cargo Rear Door →</span>
            </div>

            {/* Truck Frame Container */}
            <div className="border-4 border-slate-800 rounded-2xl bg-slate-900 p-3 shadow-inner relative overflow-hidden">

              <div className="h-full w-full bg-slate-100 rounded-xl p-3 flex flex-wrap gap-1.5 min-h-[220px] items-stretch align-content-start relative">

                {items.length > 0 ? (
                  items.map((item, index) => {
                    const itemShare = totalCbm > 0 ? (item.cbm / totalCbm) * (fillPercentage / 100) * 100 : 0;
                    const flexWidth = Math.max(8, itemShare);
                    const colorClass = ITEM_COLORS[index % ITEM_COLORS.length];

                    return (
                      <div
                        key={index}
                        style={{ flex: `1 1 ${flexWidth}%`, minWidth: '80px' }}
                        className={`p-2.5 rounded-lg border shadow-xs flex flex-col justify-between transition-all hover:scale-[1.02] cursor-pointer ${colorClass}`}
                        title={`${item.productName || item.productId}: ${item.cbm.toFixed(2)} CBM (${item.qty} units)`}
                      >
                        <div className="flex items-start justify-between gap-1">
                          <span className="text-xs font-bold truncate leading-tight">{item.productName || item.productId}</span>
                          <span className="text-[10px] bg-black/20 px-1.5 py-0.5 rounded font-mono font-bold flex-shrink-0">
                            {item.qty} pcs
                          </span>
                        </div>
                        <div className="mt-2 flex items-end justify-between text-[11px] opacity-90">
                          <span className="font-mono">{item.productId || ''}</span>
                          <span className="font-extrabold">{item.cbm.toFixed(2)} m³</span>
                        </div>
                      </div>
                    );
                  })
                ) : (
                  <div className="w-full flex items-center justify-center text-slate-400 text-sm font-medium py-12">
                    No individual item breakdown available for this order.
                  </div>
                )}

                {/* Empty Space Block */}
                {remainingCbm > 0.1 && (
                  <div 
                    style={{ flex: `1 1 ${100 - fillPercentage}%`, minWidth: '60px' }}
                    className="p-2.5 rounded-lg border-2 border-dashed border-slate-300 bg-slate-50 text-slate-400 flex flex-col items-center justify-center text-center"
                  >
                    <span className="text-xs font-bold">Unused Space</span>
                    <span className="text-[11px] font-mono">{remainingCbm.toFixed(2)} m³ Free</span>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Item Breakdown Legend Table */}
          <div>
            <h4 className="text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">Item Allocation Details</h4>
            <div className="max-h-40 overflow-y-auto border border-slate-200 rounded-xl custom-scrollbar">
              <table className="w-full text-xs text-left text-slate-600">
                <thead className="bg-slate-100 text-slate-700 uppercase font-bold text-[10px] sticky top-0">
                  <tr>
                    <th className="px-3 py-2">Item Code</th>
                    <th className="px-3 py-2">Product Name</th>
                    <th className="px-3 py-2 text-center">Unit CBM</th>
                    <th className="px-3 py-2 text-center">Quantity</th>
                    <th className="px-3 py-2 text-center">Total Volume</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {items.map((item, idx) => (
                    <tr key={idx} className="hover:bg-slate-50">
                      <td className="px-3 py-2 font-mono text-slate-700 font-semibold">{item.productId || '-'}</td>
                      <td className="px-3 py-2 font-medium">{item.productName || '-'}</td>
                      <td className="px-3 py-2 text-center text-slate-500">{(item.unitCbm || 0).toFixed(4)}</td>
                      <td className="px-3 py-2 text-center font-bold text-slate-800">{item.qty}</td>
                      <td className="px-3 py-2 text-center font-bold text-indigo-600">{(item.cbm || 0).toFixed(3)} m³</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

        </div>

        {/* Modal Footer */}
        <div className="bg-slate-50 px-6 py-4 border-t border-slate-200 flex items-center justify-between">
          <div className="flex items-center gap-2 text-xs text-slate-500">
            {fillPercentage > 100 ? (
              <span className="flex items-center gap-1 text-red-600 font-bold">
                <AlertCircle className="w-4 h-4" /> Cargo exceeds single truck capacity! Additional truck required.
              </span>
            ) : (
              <span className="flex items-center gap-1 text-emerald-600 font-semibold">
                <CheckCircle2 className="w-4 h-4" /> Optimal loading configuration for {currentTruck.name}.
              </span>
            )}
          </div>
          <button
            onClick={onClose}
            className="px-5 py-2 bg-slate-900 text-white rounded-xl font-bold text-xs hover:bg-slate-800 transition-colors shadow-xs"
          >
            Close Visualizer
          </button>
        </div>

      </div>
    </div>
  );
};

export default TruckVisualizerModal;
